INSERT INTO "ai_recommendations" ("id", "application_id", "job_posting_id", "match_score", "skills_match_percentage", "confidence_score", "recommendation", "missing_skills", "strengths", "weaknesses", "qualification_gaps", "explanation", "summary", "score_breakdown", "rank", "status", "created_at", "updated_at") VALUES (17, 29, 10, 78, 80, 75.00, 'recommended', '["Canva\/Photoshop"]', '["Advanced skills in Content Creation and Social Media Management","Experience in Destination Marketing and Campaign Execution","Strong background in SEO and market research"]', '["Limited experience with Canva\/Photoshop","No direct experience in travel blogging or video editing"]', '["Preferred skills in Travel Blogging and Video Editing are not present"]', 'Kimi Antonelli has a solid background in marketing with a focus on travel and tourism, showcasing advanced skills in Content Creation and Social Media Management. However, she lacks experience with Canva/Photoshop, which is a required skill for the role. Additionally, while she has relevant experience, her overall years in destination marketing are slightly below expectations for this position. Therefore, she is recommended for the role but with some reservations regarding her fit for specific tasks.', 'Kimi Antonelli is a strong candidate for the Destination Marketing Specialist role with notable strengths in content creation and social media management.', '{"skills":80,"experience":70,"education":60,"interview":0}', NULL, 'generated', '2026-08-25 16:58:34', '2026-08-25 16:58:34');
